#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

// Implementação rápida de GCD usando o algoritmo binário (std::gcd em C++17 já é rápido)
inline int gcd(int a, int b) {
    while (b) {
        a %= b;
        swap(a, b);
    }
    return a;
}

struct Item {
    int g;
    int cnt;
};

struct Node {
    int len;
    long long ans;
    int pref_sz, suf_sz;
    Item pref[32];
    Item suf[32];

    Node() : len(0), ans(0), pref_sz(0), suf_sz(0) {}
};

int n, m;
int s[100005];
Node tree[400005];

Node merge_nodes(const Node& L, const Node& R) {
    if (L.len == 0) return R;
    if (R.len == 0) return L;

    Node res;
    res.len = L.len + R.len;
    res.ans = L.ans + R.ans;

    // Contar subarrays que cruzam o meio
    for (int i = 0; i < L.suf_sz; ++i) {
        for (int j = 0; j < R.pref_sz; ++j) {
            if (gcd(L.suf[i].g, R.pref[j].g) > 1) {
                res.ans += 1LL * L.suf[i].cnt * R.pref[j].cnt;
            }
        }
    }

    // Construir prefixos
    res.pref_sz = L.pref_sz;
    for (int i = 0; i < L.pref_sz; ++i) {
        res.pref[i] = L.pref[i];
    }

    int L_pref_len = 0;
    for (int i = 0; i < L.pref_sz; ++i) {
        L_pref_len += L.pref[i].cnt;
    }

    if (L_pref_len == L.len && L.pref_sz > 0) {
        int g_all = L.pref[L.pref_sz - 1].g;
        for (int j = 0; j < R.pref_sz; ++j) {
            int g_new = gcd(g_all, R.pref[j].g);
            if (g_new == 1) break;
            if (res.pref_sz > 0 && res.pref[res.pref_sz - 1].g == g_new) {
                res.pref[res.pref_sz - 1].cnt += R.pref[j].cnt;
            } else {
                res.pref[res.pref_sz++] = {g_new, R.pref[j].cnt};
            }
        }
    }

    // Construir sufixos
    res.suf_sz = R.suf_sz;
    for (int i = 0; i < R.suf_sz; ++i) {
        res.suf[i] = R.suf[i];
    }

    int R_suf_len = 0;
    for (int i = 0; i < R.suf_sz; ++i) {
        R_suf_len += R.suf[i].cnt;
    }

    if (R_suf_len == R.len && R.suf_sz > 0) {
        int g_all = R.suf[R.suf_sz - 1].g;
        for (int i = 0; i < L.suf_sz; ++i) {
            int g_new = gcd(g_all, L.suf[i].g);
            if (g_new == 1) break;
            if (res.suf_sz > 0 && res.suf[res.suf_sz - 1].g == g_new) {
                res.suf[res.suf_sz - 1].cnt += L.suf[i].cnt;
            } else {
                res.suf[res.suf_sz++] = {g_new, L.suf[i].cnt};
            }
        }
    }

    return res;
}

void make_leaf(Node& node, int val) {
    node.len = 1;
    if (val > 1) {
        node.ans = 1;
        node.pref_sz = 1;
        node.pref[0] = {val, 1};
        node.suf_sz = 1;
        node.suf[0] = {val, 1};
    } else {
        node.ans = 0;
        node.pref_sz = 0;
        node.suf_sz = 0;
    }
}

void build(int u, int l, int r) {
    if (l == r) {
        make_leaf(tree[u], s[l]);
        return;
    }
    int mid = (l + r) / 2;
    build(2 * u, l, mid);
    build(2 * u + 1, mid + 1, r);
    tree[u] = merge_nodes(tree[2 * u], tree[2 * u + 1]);
}

void update(int u, int l, int r, int idx, int val) {
    if (l == r) {
        s[idx] = val;
        make_leaf(tree[u], val);
        return;
    }
    int mid = (l + r) / 2;
    if (idx <= mid) update(2 * u, l, mid, idx, val);
    else update(2 * u + 1, mid + 1, r, idx, val);
    tree[u] = merge_nodes(tree[2 * u], tree[2 * u + 1]);
}

Node query(int u, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
        return tree[u];
    }
    int mid = (l + r) / 2;
    if (qr <= mid) return query(2 * u, l, mid, ql, qr);
    if (ql > mid) return query(2 * u + 1, mid + 1, r, ql, qr);
    return merge_nodes(query(2 * u, l, mid, ql, qr), query(2 * u + 1, mid + 1, r, ql, qr));
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    if (!(cin >> n >> m)) return 0;

    for (int i = 1; i <= n; ++i) {
        cin >> s[i];
    }

    build(1, 1, n);

    for (int k = 0; k < m; ++k) {
        int t;
        cin >> t;
        if (t == 1) {
            int i, v;
            cin >> i >> v;
            update(1, 1, n, i, v);
        } else {
            int e, d;
            cin >> e >> d;
            Node res = query(1, 1, n, e, d);
            cout << res.ans << "\n";
        }
    }

    return 0;
}
